testcases.Hidden_Test_Steps_Procedure:
Entry: int test_case()
1. Call chk_rst_val().
2. If DEBUG_DISPLAY: print default-check end banner.
3. Call chk_rd_wr().
4. If DEBUG_DISPLAY: print R/W end banner.
5. If (def_fail_cnt > 0 || wr_fail_cnt > 0) finish(1); else finish(0).

Function: void chk_rst_val()
6. for (i=0; i<CNT; i++):
7.   addr = addr_array[i];
8.   if (skip_rst_array[i] == 1) continue;
9.   if (read_mask_array[i] == 0x00000000) continue;
10.  data_rd = read_reg(addr);
11.  data = (data_rd & 0xfffffffe);
12.  if (data == default_value_array[i]) { /* PASS */ } else { def_fail_cnt++; printf failure with addr, expected, data, data_rd; }

Function: void chk_rd_wr()
13. unsigned int chk_val[6] = {0xffffffff,0xaaaaaaaa,0x55555555,0xf5f5f5f5,0xA5A5A5A5,0xffff0000};
14. for (j=0; j<6; j++): data_wr = chk_val[j];
15.   // Write phase
16.   for (i=0; i<CNT; i++):
17.     addr = addr_array[i];
18.     if (skip_array[i] == 1) continue;
19.     if (write_mask_array[i] == 0x00000000) continue;
20.     write_reg(addr, (data_wr & write_mask_array[i]));
21.   // Read/compare phase
22.   for (i=0; i<CNT; i++):
23.     addr = addr_array[i];
24.     if (skip_array[i] == 1) continue;
25.     if (write_mask_array[i] == 0x00000000) continue;
26.     if (read_mask_array[i] == 0x00000000) continue;
27.     data_rd = (read_reg(addr) & read_mask_array[i]);
28.     wr_n = (write_mask_array[i] ^ 0xffffffff);
29.     exp_val = ((data_wr & read_mask_array[i] & write_mask_array[i]) | (wr_n & read_mask_array[i] & default_value_array[i]));
30.     if (data_rd == exp_val) { /* PASS */ } else { wr_fail_cnt++; printf mismatch with addr, exp_val, data_rd; }

Entry: int test_case()
1. test_err = 0.
2. If GPIO0: GIC_EnableIRQ(87); if GPIO1: GIC_EnableIRQ(88).
3. If GPIO0: write_reg(MIZAR_LSS_SYSREG_INTR_EN1, LSS_SYSREG_INTR_EN1_GPIO0_INTR); if GPIO1: write_reg(MIZAR_LSS_SYSREG_INTR_EN1, LSS_SYSREG_INTR_EN1_GPIO1_INTR).
4. write_reg(0xA0243ffc, 0xffffffff).
5. for (i=0; i<32; i++): addr1 = MIZAR_GPIO_GP0_GPIO_8 + (i*4); write_reg(addr1, (1u<<20)|(1u<<18)|(1u<<16)); wait_on(10). // doe=1, neie=1, iclr=1
6. for (i=0; i<32; i++):
7.   wr_val = 1u << i;
8.   write_reg(MIZAR_GPIO_GPIO_INTR_RAW_STCLR1, wr_val);
9.   write_reg(MIZAR_GPIO_GP0_INTR1_INTR_EN1, wr_val);
10.  wait_on(10);
11.  int_pend = 1;
12.  write_reg(0xA0243ffc, 0xffffffff); wait_on(30); write_reg(0xA0243ffc, ~wr_val);
13.  unsigned int timeout = 5000; while (int_pend && timeout--) { wait_on(10); }
14.  if (timeout == 0) { printf timeout; test_err++; }
15. finish(test_err).

ISR: void Default_IRQHandler()
16. unsigned int local_wr = 1u << i; int_pend = 0; write_reg(0xA0243ffc, 0xffffffff);
17. unsigned int raddr = MIZAR_GPIO_GP0_GPIO_8 + (i*4); rdata = read_reg(raddr);
18. if ((rdata & 0x1) != 0) test_err++; // DIN must be 0 after negedge
19. if ((rdata & 0x2) != 0x0) {
20.   unsigned int rdata_grp = read_reg(MIZAR_GPIO_GP0_INTR1_INTR_STS1);
21.   if ((rdata_grp & local_wr) == 0) test_err++;
22.   unsigned int raddr2 = MIZAR_GPIO_GP0_GPIO_8 + (i*4); write_reg(raddr2, (1u<<20)|(1u<<16)); // doe=1, iclr=1
23.   write_reg(MIZAR_GPIO_GPIO_INTR_RAW_STCLR1, local_wr);
24.   rdata_grp = read_reg(MIZAR_GPIO_GP0_INTR1_INTR_STS1); if (rdata_grp != 0x0) test_err++;
25.   if GPIO0: write_reg(MIZAR_LSS_SYSREG_RAW_STCR1, LSS_SYSREG_RAW_STCR1_GPIO0_INTR); GIC_ClearIRQ(87);
26.   if GPIO1: write_reg(MIZAR_LSS_SYSREG_RAW_STCR1, LSS_SYSREG_RAW_STCR1_GPIO1_INTR); GIC_ClearIRQ(88);
27. } else { test_err++; }
